[metadata] {"type": "create", "filePath": "/app/global-internet-usage-infographic.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>Global Internet Usage 2025 - Infographic</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body {
      font-family: 'Segoe UI', 'Inter', system-ui, -apple-system, sans-serif;
      background: #0a0f1e;
      color: white;
      width: 1240px;
    }

    .poster {
      width: 1240px;
      background: #0a0f1e;
      padding: 56px 64px 48px;
      position: relative;
      overflow: hidden;
    }

    /* Subtle dot grid background */
    .poster::before {
      content: '';
      position: absolute;
      inset: 0;
      background-image: radial-gradient(circle, rgba(6,182,212,0.06) 1px, transparent 1px);
      background-size: 44px 44px;
      pointer-events: none;
      z-index: 0;
    }

    /* Glow orbs */
    .glow-tl {
      position: absolute;
      top: -120px; left: -120px;
      width: 480px; height: 480px;
      background: radial-gradient(circle, rgba(6,182,212,0.08) 0%, transparent 70%);
      pointer-events: none;
    }
    .glow-br {
      position: absolute;
      bottom: -100px; right: -100px;
      width: 400px; height: 400px;
      background: radial-gradient(circle, rgba(99,102,241,0.07) 0%, transparent 70%);
      pointer-events: none;
    }

    .content { position: relative; z-index: 1; }

    /* ── HEADER ── */
    .header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      padding-bottom: 20px;
      border-bottom: 1px solid rgba(6,182,212,0.25);
      margin-bottom: 44px;
    }
    .header-badge {
      display: flex; align-items: center; gap: 8px;
    }
    .header-dot { width: 6px; height: 6px; background: #06b6d4; border-radius: 50%; }
    .header-label {
      font-size: 10.5px; font-weight: 700;
      letter-spacing: 3px; text-transform: uppercase; color: #06b6d4;
    }
    .header-right { font-size: 10.5px; color: rgba(255,255,255,0.3); letter-spacing: 1px; }

    /* ── TITLE ── */
    .title-block { margin-bottom: 40px; }
    .main-title {
      font-size: 54px; font-weight: 900;
      line-height: 1.08; letter-spacing: -1.5px;
      color: white; margin-bottom: 14px;
    }
    .main-title .accent { color: #06b6d4; }
    .subtitle {
      font-size: 15px; color: rgba(255,255,255,0.45);
      font-weight: 400; line-height: 1.65; max-width: 640px;
    }

    /* ── HERO STAT ── */
    .hero-stat {
      background: linear-gradient(135deg, rgba(6,182,212,0.1) 0%, rgba(14,165,233,0.05) 100%);
      border: 1px solid rgba(6,182,212,0.28);
      border-radius: 18px;
      padding: 36px 48px;
      margin-bottom: 48px;
      display: flex;
      align-items: center;
      gap: 52px;
    }
    .hero-number {
      font-size: 96px; font-weight: 900;
      color: #06b6d4; line-height: 1; letter-spacing: -4px;
      white-space: nowrap; flex-shrink: 0;
    }
    .hero-meta { flex: 1; }
    .hero-label-main {
      font-size: 22px; font-weight: 800; color: white; margin-bottom: 6px;
    }
    .hero-label-sub {
      font-size: 15px; font-weight: 300; color: rgba(255,255,255,0.65); line-height: 1.6;
    }
    .hero-pills {
      display: flex; gap: 12px; margin-top: 14px;
    }
    .hero-pill {
      font-size: 11px; font-weight: 600;
      background: rgba(6,182,212,0.12); color: rgba(6,182,212,0.9);
      border: 1px solid rgba(6,182,212,0.2);
      border-radius: 20px; padding: 4px 14px;
      letter-spacing: 0.5px;
    }

    /* ── SECTION LABEL ── */
    .section-label {
      display: flex; align-items: center; gap: 10px; margin-bottom: 14px;
    }
    .section-label-dot { width: 7px; height: 7px; background: #06b6d4; border-radius: 50%; }
    .section-label-text {
      font-size: 10px; font-weight: 700;
      letter-spacing: 2.5px; text-transform: uppercase; color: #06b6d4;
    }

    /* ── PENETRATION CHART ── */
    .chart-section { margin-bottom: 44px; }
    .chart-heading {
      font-size: 26px; font-weight: 800; color: white; margin-bottom: 6px;
    }
    .chart-subhead {
      font-size: 12.5px; color: rgba(255,255,255,0.35); margin-bottom: 22px;
    }
    .bar-chart { display: flex; flex-direction: column; gap: 10px; }
    .bar-row {
      display: flex; align-items: center; gap: 14px;
    }
    .bar-country {
      font-size: 12.5px; font-weight: 600; color: rgba(255,255,255,0.75);
      width: 130px; text-align: right; flex-shrink: 0;
    }
    .bar-track {
      flex: 1; height: 28px;
      background: rgba(255,255,255,0.05);
      border-radius: 6px; overflow: hidden; position: relative;
    }
    .bar-fill {
      height: 100%; border-radius: 6px;
      position: relative; display: flex; align-items: center;
    }
    .bar-value {
      font-size: 11.5px; font-weight: 700;
      position: absolute; right: 10px; color: white;
    }

    /* Color scale by value */
    .bar-fill.top    { background: linear-gradient(90deg, #0e7490, #06b6d4); }
    .bar-fill.high   { background: linear-gradient(90deg, #0369a1, #0ea5e9); }
    .bar-fill.mid    { background: linear-gradient(90deg, #1d4ed8, #3b82f6); }
    .bar-fill.low    { background: linear-gradient(90deg, #4338ca, #6366f1); }
    .bar-fill.lowest { background: linear-gradient(90deg, #5b21b6, #8b5cf6); }

    /* Highlight China & India */
    .bar-row.highlight-china .bar-country { color: #f87171; font-weight: 700; }
    .bar-row.highlight-india  .bar-country { color: #fbbf24; font-weight: 700; }
    .bar-row.highlight-china .bar-fill { background: linear-gradient(90deg, #991b1b, #f87171); }
    .bar-row.highlight-india  .bar-fill { background: linear-gradient(90deg, #92400e, #fbbf24); }

    /* ── ASIA CALLOUTS ── */
    .callouts { display: grid; grid-template-columns: 1fr 1fr; gap: 20px; margin-bottom: 44px; }
    .callout-card {
      border-radius: 16px; padding: 28px 32px;
      position: relative; overflow: hidden;
    }
    .callout-card.china {
      background: linear-gradient(135deg, rgba(239,68,68,0.1) 0%, rgba(10,15,30,0.95) 100%);
      border: 1px solid rgba(239,68,68,0.28);
    }
    .callout-card.india {
      background: linear-gradient(135deg, rgba(245,158,11,0.1) 0%, rgba(10,15,30,0.95) 100%);
      border: 1px solid rgba(245,158,11,0.28);
    }
    .callout-flag { font-size: 28px; margin-bottom: 10px; }
    .callout-country {
      font-size: 10px; font-weight: 700; letter-spacing: 2.5px;
      text-transform: uppercase; color: rgba(255,255,255,0.4); margin-bottom: 8px;
    }
    .callout-users {
      font-size: 52px; font-weight: 900; line-height: 1; letter-spacing: -2px; margin-bottom: 4px;
    }
    .china .callout-users { color: #f87171; }
    .india .callout-users { color: #fbbf24; }
    .callout-unit { font-size: 12.5px; color: rgba(255,255,255,0.35); margin-bottom: 14px; }
    .callout-badge {
      display: inline-block; font-size: 11px; font-weight: 700;
      padding: 5px 14px; border-radius: 20px; letter-spacing: 0.5px;
    }
    .china .callout-badge { background: rgba(239,68,68,0.15); color: #f87171; }
    .india .callout-badge { background: rgba(245,158,11,0.15); color: #fbbf24; }

    /* ── PLATFORMS ── */
    .platforms-section { margin-bottom: 44px; }
    .platforms-heading {
      font-size: 22px; font-weight: 800; color: white; margin-bottom: 6px;
    }
    .platforms-sub { font-size: 12.5px; color: rgba(255,255,255,0.35); margin-bottom: 20px; }
    .platforms-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px; }
    .platform-card {
      background: rgba(255,255,255,0.03); border: 1px solid rgba(255,255,255,0.07);
      border-radius: 12px; padding: 18px 14px; text-align: center;
    }
    .platform-name {
      font-size: 10.5px; font-weight: 700; text-transform: uppercase;
      letter-spacing: 1px; color: rgba(255,255,255,0.4); margin-bottom: 8px;
    }
    .platform-mau {
      font-size: 24px; font-weight: 900; color: white; line-height: 1; margin-bottom: 4px;
    }
    .platform-unit { font-size: 9.5px; color: rgba(255,255,255,0.25); }

    /* Daily usage bar visual */
    .usage-bar-wrap { margin-top: 10px; display: flex; align-items: center; gap: 8px; }
    .usage-bar-bg { flex: 1; height: 4px; background: rgba(255,255,255,0.07); border-radius: 2px; overflow: hidden; }
    .usage-bar-fill { height: 100%; background: linear-gradient(90deg, #06b6d4, #6366f1); border-radius: 2px; }
    .usage-bar-label { font-size: 9px; color: rgba(255,255,255,0.25); white-space: nowrap; }

    /* ── ECONOMY SECTION ── */
    .economy-section {
      background: linear-gradient(135deg, rgba(6,182,212,0.07) 0%, rgba(99,102,241,0.07) 100%);
      border: 1px solid rgba(6,182,212,0.18);
      border-radius: 20px;
      padding: 36px 48px;
      margin-bottom: 44px;
    }
    .economy-top { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 28px; }
    .economy-heading { font-size: 26px; font-weight: 800; color: white; }
    .economy-subhead { font-size: 12.5px; color: rgba(255,255,255,0.35); margin-top: 4px; }
    .economy-cta {
      font-size: 11px; font-weight: 700;
      background: rgba(6,182,212,0.12); color: #06b6d4;
      border: 1px solid rgba(6,182,212,0.25);
      border-radius: 20px; padding: 6px 18px; letter-spacing: 0.5px;
    }
    .economy-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }
    .economy-stat { text-align: center; }
    .economy-value {
      font-size: 40px; font-weight: 900; color: #06b6d4;
      line-height: 1; letter-spacing: -1px; margin-bottom: 8px;
    }
    .economy-label {
      font-size: 11px; font-weight: 600; text-transform: uppercase;
      letter-spacing: 1px; color: rgba(255,255,255,0.4); line-height: 1.5;
    }
    .economy-divider { border: none; border-left: 1px solid rgba(255,255,255,0.08); height: 60px; align-self: center; }

    /* ── TAKEAWAYS ── */
    .takeaways-section { margin-bottom: 44px; }
    .takeaways-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 14px; }
    .takeaway {
      display: flex; gap: 16px; align-items: flex-start;
      background: rgba(255,255,255,0.028);
      border: 1px solid rgba(255,255,255,0.065);
      border-radius: 12px; padding: 18px 20px;
    }
    .takeaway-num {
      font-size: 36px; font-weight: 900;
      color: rgba(6,182,212,0.18); line-height: 1; flex-shrink: 0;
    }
    .takeaway-text { font-size: 13px; color: rgba(255,255,255,0.55); line-height: 1.65; padding-top: 4px; }

    /* ── FOOTER ── */
    .footer {
      border-top: 1px solid rgba(255,255,255,0.07);
      padding-top: 20px;
      display: flex;
      justify-content: space-between;
      align-items: center;
    }
    .footer-src { font-size: 10.5px; color: rgba(255,255,255,0.18); }
    .footer-badge { font-size: 10.5px; font-weight: 700; color: rgba(6,182,212,0.45); letter-spacing: 1.5px; }
  </style>
</head>
